        /// <param name="offset">the offset, in bytes, from the beginning of the string if >= 0, the offset from the end of the string if &lt; 0. Note that this does not do UTF-8 validation, so you should only insert at UTF-8 sequence boundaries.</param>
        /// <param name="string">the UTF-8 text to insert.</param>
        /// <param name="length">the length of the text, in bytes, or 0 for null terminated text.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>This function should be called on the thread that created the text.</threadsafety>
        /// <since>This function is available since SDL_ttf 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_ttf/TTF_InsertTextString">TTF_InsertTextString</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.TTF.TextObject.AppendString">AppendString</see></seealso>
        /// <seealso><see cref="CSDL.TTF.TextObject.DeleteString">DeleteString</see></seealso>
        /// <seealso><see cref="CSDL.TTF.TextObject.SetString">SetString</see></seealso>
        public static extern void InsertTextString();

        /// <summary>
        /// <para>Calculate how much of a UTF-8 string will fit in a given width.</para>
        /// </summary>
        /// <remarks>
        /// <para>This reports the number of characters that can be rendered before reaching <c>max_width</c>.</para>
        /// <para>This does not need to render the string to do this calculation.</para>
        /// </remarks>
        /// <param name="font">the font to query.</param>
        /// <param name="text">text to calculate, in UTF-8 encoding.</param>
        /// <param name="length">the length of the text, in bytes, or 0 for null terminated text.</param>
        /// <param name="max_width">maximum width, in pixels, available for the string, or 0 for unbounded width.</param>
        /// <param name="measured_width">a pointer filled in with the width, in pixels, of the string that will fit, may be NULL.</param>
        /// <param name="measured_length">a pointer filled in with the length, in bytes, of the string that will fit, may be NULL.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>This function should be called on the thread that created the font.</threadsafety>
        /// <since>This function is available since SDL_ttf 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_ttf/TTF_MeasureString">TTF_MeasureString</seealso></SDLWiki>
        public static extern void MeasureString();

        /// <summary>
        /// <para>Create a font from a file, using a specified point size.</para>
        /// </summary>
        /// <remarks>
        /// <para>Some .fon fonts will have several sizes embedded in the file, so the point size becomes the index of choosing which size. If the value is too high, the last indexed size will be the default.</para>
        /// <para>When done with the returned <c>TTF_Font</c>, use <see cref="CSDL.TTF.Font.DisposeResource">DisposeResource</see> to dispose of it.</para>
        /// </remarks>
        /// <param name="file">path to font file.</param>
        /// <param name="ptsize">point size to use for the newly-opened font.</param>
