        /// <para>(<c>TTF_Font</c> *) Returns a valid <c>TTF_Font</c>, or NULL on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_ttf 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_ttf/TTF_OpenFont">TTF_OpenFont</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.TTF.Font.DisposeResource">DisposeResource</see></seealso>
        public static extern void OpenFont();

        /// <summary>
        /// <para>Create a font from an SDL_IOStream, using a specified point size.</para>
        /// </summary>
        /// <remarks>
        /// <para>Some .fon fonts will have several sizes embedded in the file, so the point size becomes the index of choosing which size. If the value is too high, the last indexed size will be the default.</para>
        /// <para>If <c>closeio</c> is true, <c>src</c> will be automatically closed once the font is closed. Otherwise you should keep <c>src</c> open until the font is closed.</para>
        /// <para>When done with the returned <c>TTF_Font</c>, use <see cref="CSDL.TTF.Font.DisposeResource">DisposeResource</see> to dispose of it.</para>
        /// </remarks>
        /// <param name="src">an SDL_IOStream to provide a font file's data.</param>
        /// <param name="closeio">true to close <c>src</c> when the font is closed, false to leave it open.</param>
        /// <param name="ptsize">point size to use for the newly-opened font.</param>
        /// <returns>
        /// <para>(<c>TTF_Font</c> *) Returns a valid <c>TTF_Font</c>, or NULL on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_ttf 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_ttf/TTF_OpenFontIO">TTF_OpenFontIO</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.TTF.Font.DisposeResource">DisposeResource</see></seealso>
        public static extern void OpenFontIO();

        /// <summary>
        /// <para>Create a font with the specified properties.</para>
        /// </summary>
        /// <remarks>
        /// <para>These are the supported properties:</para>
        /// <list type="bullet">
        /// <item><description><see cref="PropFontCreateFilenameString"/>: the font file to open, if an SDL_IOStream isn't being used. This is required if <see cref="PropFontCreateIostreamPointer"/> and <see cref="PropFontCreateExistingFontPointer"/> aren't set.</description></item>
        /// <item><description><see cref="PropFontCreateIostreamPointer"/>: an SDL_IOStream containing the font to be opened. This should not be closed until the font is closed. This is required if <see cref="PropFontCreateFilenameString"/> and <see cref="PropFontCreateExistingFontPointer"/> aren't set.</description></item>
        /// <item><description><see cref="PropFontCreateIostreamOffsetNumber"/>: the offset in the iostream for the beginning of the font, defaults to 0.</description></item>
        /// <item><description><see cref="PropFontCreateIostreamAutocloseBoolean"/>: true if closing the font should also close the associated SDL_IOStream.</description></item>
        /// <item><description><see cref="PropFontCreateSizeFloat"/>: the point size of the font. Some .fon fonts will have several sizes embedded in the file, so the point size becomes the index of choosing which size. If the value is too high, the last indexed size will be the default.</description></item>
        /// <item><description><see cref="PropFontCreateFaceNumber"/>: the face index of the font, if the font contains multiple font faces.</description></item>
        /// <item><description><see cref="PropFontCreateHorizontalDpiNumber"/>: the horizontal DPI to use for font rendering, defaults to <see cref="PropFontCreateVerticalDpiNumber"/> if set, or 72 otherwise.</description></item>
        /// <item><description><see cref="PropFontCreateVerticalDpiNumber"/>: the vertical DPI to use for font rendering, defaults to <see cref="PropFontCreateHorizontalDpiNumber"/> if set, or 72 otherwise.</description></item>
        /// <item><description><see cref="PropFontCreateExistingFontPointer"/>: an optional <c>TTF_Font</c> that, if set, will be used as the font data source and the initial size and style of the new font.</description></item>
        /// </list>
        /// </remarks>
        /// <param name="props">the properties to use.</param>
        /// <returns>
        /// <para>(<c>TTF_Font</c> *) Returns a valid <c>TTF_Font</c>, or NULL on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_ttf 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_ttf/TTF_OpenFontWithProperties">TTF_OpenFontWithProperties</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.TTF.Font.DisposeResource">DisposeResource</see></seealso>
        public static extern void OpenFontWithProperties();

        /// <summary>
        /// <para>Deinitialize SDL_ttf.</para>
