        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_ttf/TTF_SetGPUTextEngineWinding">TTF_SetGPUTextEngineWinding</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.TTF.GPUTextEngine.Winding">Winding</see></seealso>
        public static extern void SetGPUTextEngineWinding();

        /// <summary>
        /// <para>Set the color of a text object.</para>
        /// </summary>
        /// <remarks>
        /// <para>The default text color is white (255, 255, 255, 255).</para>
        /// </remarks>
        /// <param name="text">the <see cref="CSDL.TTF.Text">Text</see> to modify.</param>
        /// <param name="r">the red color value in the range of 0-255.</param>
        /// <param name="g">the green color value in the range of 0-255.</param>
        /// <param name="b">the blue color value in the range of 0-255.</param>
        /// <param name="a">the alpha value in the range of 0-255.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>This function should be called on the thread that created the text.</threadsafety>
        /// <since>This function is available since SDL_ttf 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_ttf/TTF_SetTextColor">TTF_SetTextColor</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.TTF.TextObject.Color">Color</see></seealso>
        /// <seealso><c>TTF_SetTextColorFloat</c></seealso>
        public static extern void SetTextColor();

        /// <summary>
        /// <para>Set the color of a text object.</para>
        /// </summary>
        /// <remarks>
        /// <para>The default text color is white (1.0f, 1.0f, 1.0f, 1.0f).</para>
        /// </remarks>
        /// <param name="text">the <see cref="CSDL.TTF.Text">Text</see> to modify.</param>
        /// <param name="r">the red color value, normally in the range of 0-1.</param>
        /// <param name="g">the green color value, normally in the range of 0-1.</param>
        /// <param name="b">the blue color value, normally in the range of 0-1.</param>
        /// <param name="a">the alpha value in the range of 0-1.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>This function should be called on the thread that created the text.</threadsafety>
        /// <since>This function is available since SDL_ttf 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_ttf/TTF_SetTextColorFloat">TTF_SetTextColorFloat</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.TTF.TextObject.FloatColor">FloatColor</see></seealso>
        /// <seealso><c>TTF_SetTextColor</c></seealso>
        public static extern void SetTextColorFloat();

        /// <summary>
        /// <para>Set the direction to be used for text shaping a text object.</para>
        /// </summary>
        /// <remarks>
        /// <para>This function only supports left-to-right text shaping if SDL_ttf was not built with HarfBuzz support.</para>
        /// </remarks>
        /// <param name="text">the text to modify.</param>
        /// <param name="direction">the new direction for text to flow.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>This function should be called on the thread that created the text.</threadsafety>
        /// <since>This function is available since SDL_ttf 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_ttf/TTF_SetTextDirection">TTF_SetTextDirection</seealso></SDLWiki>
        public static extern void SetTextDirection();

        /// <summary>
        /// <para>Set the text engine used by a text object.</para>
        /// </summary>
        /// <remarks>
        /// <para>This function may cause the internal text representation to be rebuilt.</para>
        /// </remarks>
        /// <param name="text">the <see cref="CSDL.TTF.Text">Text</see> to modify.</param>
        /// <param name="engine">the text engine to use for drawing.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>This function should be called on the thread that created the text.</threadsafety>
        /// <since>This function is available since SDL_ttf 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_ttf/TTF_SetTextEngine">TTF_SetTextEngine</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.TTF.TextObject.Engine">Engine</see></seealso>
        public static extern void SetTextEngine();

        /// <summary>
        /// <para>Set the font used by a text object.</para>
        /// </summary>
        /// <remarks>
        /// <para>When a text object has a font, any changes to the font will automatically regenerate the text. If you set the font to NULL, the text will continue to render but changes to the font will no longer affect the text.</para>
        /// <para>This function may cause the internal text representation to be rebuilt.</para>
        /// </remarks>
        /// <param name="text">the <see cref="CSDL.TTF.Text">Text</see> to modify.</param>
        /// <param name="font">the font to use, may be NULL.</param>
        /// <returns>
        /// <para>(bool) Returns false if the text pointer is null; otherwise, true. call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>This function should be called on the thread that created the text.</threadsafety>
        /// <since>This function is available since SDL_ttf 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_ttf/TTF_SetTextFont">TTF_SetTextFont</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.TTF.TextObject.Font">Font</see></seealso>
        public static extern void SetTextFont();

        /// <summary>
        /// <para>Set the position of a text object.</para>
        /// </summary>
        /// <remarks>
        /// <para>This can be used to position multiple text objects within a single wrapping text area.</para>
        /// <para>This function may cause the internal text representation to be rebuilt.</para>
        /// </remarks>
        /// <param name="text">the <see cref="CSDL.TTF.Text">Text</see> to modify.</param>
        /// <param name="x">the x offset of the upper left corner of this text in pixels.</param>
        /// <param name="y">the y offset of the upper left corner of this text in pixels.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>This function should be called on the thread that created the text.</threadsafety>
        /// <since>This function is available since SDL_ttf 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_ttf/TTF_SetTextPosition">TTF_SetTextPosition</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.TTF.TextObject.GetPosition">GetPosition</see></seealso>
        public static extern void SetTextPosition();

        /// <summary>
        /// <para>Set the script to be used for text shaping a text object.</para>
        /// </summary>
        /// <remarks>
        /// <para>This returns false if SDL_ttf isn't built with HarfBuzz support.</para>
        /// </remarks>
        /// <param name="text">the text to modify.</param>
        /// <param name="script">an <a href="https://unicode.org/iso15924/iso15924-codes.html">ISO 15924 code</a> .</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>This function should be called on the thread that created the text.</threadsafety>
        /// <since>This function is available since SDL_ttf 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_ttf/TTF_SetTextScript">TTF_SetTextScript</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.TTF.TTF.StringToTag">StringToTag</see></seealso>
        public static extern void SetTextScript();

        /// <summary>
        /// <para>Set the UTF-8 text used by a text object.</para>
        /// </summary>
        /// <remarks>
        /// <para>This function may cause the internal text representation to be rebuilt.</para>
        /// </remarks>
        /// <param name="text">the <see cref="CSDL.TTF.Text">Text</see> to modify.</param>
        /// <param name="string">the UTF-8 text to use, may be NULL.</param>
        /// <param name="length">the length of the text, in bytes, or 0 for null terminated text.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>This function should be called on the thread that created the text.</threadsafety>
        /// <since>This function is available since SDL_ttf 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_ttf/TTF_SetTextString">TTF_SetTextString</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.TTF.TextObject.AppendString">AppendString</see></seealso>
        /// <seealso><see cref="CSDL.TTF.TextObject.DeleteString">DeleteString</see></seealso>
        /// <seealso><see cref="CSDL.TTF.TextObject.InsertString">InsertString</see></seealso>
        public static extern void SetTextString();

        /// <summary>
        /// <para>Set whether whitespace should be visible when wrapping a text object.</para>
        /// </summary>
        /// <remarks>
        /// <para>If the whitespace is visible, it will take up space for purposes of alignment and wrapping. This is good for editing, but looks better when centered or aligned if whitespace around line wrapping is hidden. This defaults false.</para>
        /// <para>This function may cause the internal text representation to be rebuilt.</para>
        /// </remarks>
        /// <param name="text">the <see cref="CSDL.TTF.Text">Text</see> to modify.</param>
        /// <param name="visible">true to show whitespace when wrapping text, false to hide it.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>This function should be called on the thread that created the text.</threadsafety>
        /// <since>This function is available since SDL_ttf 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_ttf/TTF_SetTextWrapWhitespaceVisible">TTF_SetTextWrapWhitespaceVisible</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.TTF.TextObject.WrapWhitespaceVisible">WrapWhitespaceVisible</see></seealso>
        public static extern void SetTextWrapWhitespaceVisible();

        /// <summary>
        /// <para>Set whether wrapping is enabled on a text object.</para>
        /// </summary>
        /// <remarks>
        /// <para>This function may cause the internal text representation to be rebuilt.</para>
        /// </remarks>
        /// <param name="text">the <see cref="CSDL.TTF.Text">Text</see> to modify.</param>
        /// <param name="wrap_width">the maximum width in pixels, 0 to wrap on newline characters.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>This function should be called on the thread that created the text.</threadsafety>
        /// <since>This function is available since SDL_ttf 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_ttf/TTF_SetTextWrapWidth">TTF_SetTextWrapWidth</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.TTF.TextObject.GetWrapWidth">GetWrapWidth</see></seealso>
        public static extern void SetTextWrapWidth();

        /// <summary>
        /// <para>Convert from a 4 character string to a 32-bit tag.</para>
        /// </summary>
        /// <param name="string">the 4 character string to convert.</param>
        /// <returns>
        /// <para>(Uint32) Returns the 32-bit representation of the string.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_ttf 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_ttf/TTF_StringToTag">TTF_StringToTag</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.TTF.TTF.TagToString">TagToString</see></seealso>
        public static extern void StringToTag();

        /// <summary>
        /// <para>Convert from a 32-bit tag to a 4 character string.</para>
        /// </summary>
        /// <param name="tag">the 32-bit tag to convert.</param>
        /// <param name="string">a pointer filled in with the 4 character representation of the tag.</param>
        /// <param name="size">the size of the buffer pointed at by string, should be at least 4.</param>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_ttf 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_ttf/TTF_TagToString">TTF_TagToString</seealso></SDLWiki>
        /// <seealso><see cref="TagToString"/></seealso>
        public static extern void TagToString();

        /// <summary>
        /// <para>Return whether whitespace is shown when wrapping a text object.</para>
        /// </summary>
        /// <param name="text">the <see cref="CSDL.TTF.Text">Text</see> to query.</param>
        /// <returns>
        /// <para>(bool) Returns true if whitespace is shown when wrapping text, or false otherwise.</para>
        /// </returns>
        /// <threadsafety>This function should be called on the thread that created the text.</threadsafety>
        /// <since>This function is available since SDL_ttf 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_ttf/TTF_TextWrapWhitespaceVisible">TTF_TextWrapWhitespaceVisible</seealso></SDLWiki>
        /// <seealso><c>TTF_SetTextWrapWhitespaceVisible</c></seealso>
        public static extern void TextWrapWhitespaceVisible();

        /// <summary>
        /// <para>Update the layout of a text object.</para>
        /// </summary>
        /// <remarks>
        /// <para>This is automatically done when the layout is requested or the text is rendered, but you can call this if you need more control over the timing of when the layout and text engine representation are updated.</para>
        /// </remarks>
        /// <param name="text">the <see cref="CSDL.TTF.Text">Text</see> to update.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>This function should be called on the thread that created the text.</threadsafety>
        /// <since>This function is available since SDL_ttf 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_ttf/TTF_UpdateText">TTF_UpdateText</seealso></SDLWiki>
        public static extern void UpdateText();

        /// <summary>
        /// <para>This function gets the version of the dynamically linked SDL_ttf library.</para>
        /// </summary>
        /// <returns>
        /// <para>(int) Returns SDL_ttf version.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_ttf 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_ttf/TTF_Version">TTF_Version</seealso></SDLWiki>
        public static extern void Version();

        /// <summary>
        /// <para>Check if SDL_ttf is initialized.</para>
        /// </summary>
        /// <remarks>
        /// <para>This reports the number of times the library has been initialized by a call to <c>TTF_Init</c>, without a paired deinitialization request from <see cref="CSDL.TTF.TTF.Quit">Quit</see>.</para>
        /// <para>In short: if it's greater than zero, the library is currently initialized and ready to work. If zero, it is not initialized.</para>
        /// <para>Despite the return value being a signed integer, this function should not return a negative number.</para>
        /// </remarks>
        /// <returns>
        /// <para>(int) Returns the current number of initialization calls, that need to eventually be paired with this many calls to <see cref="CSDL.TTF.TTF.Quit">Quit</see>.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_ttf 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_ttf/TTF_WasInit">TTF_WasInit</seealso></SDLWiki>
        /// <seealso><c>TTF_Init</c></seealso>
        /// <seealso><see cref="CSDL.TTF.TTF.Quit">Quit</see></seealso>
        public static extern void WasInit();
    }
}
